#![allow(clippy::unwrap_used)]
//! KANTOR PATCH (functions): the FORECAST.ETS family.
//!
//! Expected values were recorded from Excel: the cases formulon keeps in
//! `tests/oracle/targets/mac-365-en_US/golden/forecast_ets.golden.json`
//! (Excel 365 for Mac 16.114.1; Windows Excel 365 gives the same), and Lewis
//! Walsh's workbook `Forecast_ETS.xlsx`
//! (<https://github.com/Lewis-Walsh/Excel_Forecast.ETS>), which has none of
//! the same data. Numbers must match to the last bit.

use crate::cell::CellValue;
use crate::test::util::new_empty_model;
use crate::Model;

fn value(model: &Model, cell: &str) -> Result<f64, String> {
    let (row, column) = match cell {
        "B1" => (1, 2),
        _ => panic!("unexpected cell"),
    };
    match model.get_cell_value_by_index(0, row, column).unwrap() {
        CellValue::Number(f) => Ok(f),
        CellValue::String(s) => Err(s),
        other => panic!("unexpected value {other:?}"),
    }
}

fn check(cases: &[(&str, Result<f64, &str>)]) {
    let mut failures = Vec::new();
    for (formula, expected) in cases {
        let mut model = new_empty_model();
        model._set("A1", "13");
        model._set("A2", "14.5");
        model._set("B1", &format!("={formula}"));
        model.evaluate();
        let got = value(&model, "B1");
        let ok = match (expected, &got) {
            (Ok(e), Ok(g)) => e.to_bits() == g.to_bits(),
            (Err(e), Err(g)) => e == g,
            _ => false,
        };
        if !ok {
            failures.push(format!("{formula}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

