const WALSH_VALUES: &str = "{100;103.13295071903731;103.24302090163604;107.33021698639537;111.18648793662243;115.89308706471924;120.86473125246958;126.73579246235465;133.49560493007226;136.55761315379047;146.73579246235465;156.55761315379047;163.62739828130091}";
const WALSH_DATES: &str =
    "{39814;40179;40544;40909;41275;41640;42005;42370;42736;43101;43466;43831;44197}";

#[test]
fn walsh_workbook_results() {
    let v = WALSH_VALUES;
    let t = WALSH_DATES;
    let stat = |k: u8| format!("FORECAST.ETS.STAT({v},{t},{k},1,1)");
    let cases: Vec<(String, Result<f64, &str>)> = vec![
        (stat(1), Ok(0.5)),
        (stat(2), Ok(0.499)),
        (stat(3), Ok(f64::EPSILON)),
        (stat(4), Ok(0.650_108_785_476_961_3)),
        (stat(5), Ok(1.711_792_252_495_992_3E-2)),
        (stat(6), Ok(2.483_024_795_209_354_3)),
        (stat(7), Ok(2.927_296_808_258_728_5)),
        (
            format!("FORECAST.ETS(44562,{v},{t},0,1)"),
            Ok(172.835_393_766_246_45),
        ),
        (
            format!("FORECAST.ETS(44927,{v},{t},0,1)"),
            Ok(182.100_203_927_551_63),
        ),
        (
            format!("FORECAST.ETS(45292,{v},{t},0,1)"),
            Ok(191.365_014_088_856_84),
        ),
        (
            format!("FORECAST.ETS(45658,{v},{t},0,1)"),
            Ok(200.629_824_250_162_05),
        ),
        (
            format!("FORECAST.ETS(44562,{v},{t},0,1)-FORECAST.ETS.CONFINT(44562,{v},{t},0.95,0,1)"),
            Ok(167.467_733_915_232_8),
        ),
        (
            format!("FORECAST.ETS(45658,{v},{t},0,1)+FORECAST.ETS.CONFINT(45658,{v},{t},0.95,0,1)"),
            Ok(216.028_567_354_643_2),
        ),
    ];
    let cases: Vec<(&str, Result<f64, &str>)> =
        cases.iter().map(|(f, e)| (f.as_str(), *e)).collect();
    check(&cases);
}
